{"filePath":"/testbed/src/payhook/receiver.py","content":"import hashlib
import hmac
import json

from payhook.errors import InvalidNotification

_SIGNATURE_PREFIX = "v1="
_MAX_SKEW_SECONDS = 300
_CURRENCY_LETTERS = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZ")


def _get_header(headers, name):
    if not hasattr(headers, "items"):
        return None
    target = name.lower()
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == target:
            return value
    return None


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    timestamp = _get_header(headers, "X-Pay-Timestamp")
    signature = _get_header(headers, "X-Pay-Signature")
    if not isinstance(timestamp, str) or not isinstance(signature, str):
        raise InvalidNotification("missing timestamp or signature header")

    if isinstance(raw_body, str):
        body = raw_body.encode("utf-8")
    elif isinstance(raw_body, (bytes, bytearray, memoryview)):
        body = bytes(raw_body)
    else:
        raise InvalidNotification("unsupported body type")

    key = secret.encode("utf-8") if isinstance(secret, str) else secret

    try:
        timestamp_bytes = timestamp.encode("ascii")
    except UnicodeEncodeError:
        raise InvalidNotification("timestamp is not ASCII")

    if not signature.startswith(_SIGNATURE_PREFIX):
        raise InvalidNotification("unsupported signature scheme")
    provided = signature[len(_SIGNATURE_PREFIX):].encode("utf-8")
    expected = hmac.new(key, timestamp_bytes + b"." + body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected.encode("utf-8"), provided):
        raise InvalidNotification("signature mismatch")

    try:
        stamp = int(timestamp)
    except ValueError:
        raise InvalidNotification("malformed timestamp")
    if abs(now - stamp) > _MAX_SKEW_SECONDS:
        raise InvalidNotification("stale timestamp")

    try:
        data = json.loads(body)
    except ValueError:
        raise InvalidNotification("malformed JSON body")
    if not isinstance(data, dict):
        raise InvalidNotification("payload is not a JSON object")

    event_id = data.get("event_id")
    account_id = data.get("account_id")
    amount_minor = data.get("amount_minor")
    currency = data.get("currency")

    if not isinstance(event_id, str) or event_id == "":
        raise InvalidNotification("invalid event_id")
    if not isinstance(account_id, str) or account_id == "":
        raise InvalidNotification("invalid account_id")
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int) or amount_minor < 0:
        raise InvalidNotification("invalid amount_minor")
    if (
        not isinstance(currency, str)
        or len(currency) != 3
        or any(char not in _CURRENCY_LETTERS for char in currency)
    ):
        raise InvalidNotification("invalid currency")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }
"}

