import hashlib, hmac, json
from payhook.errors import InvalidNotification
from payhook.receiver import parse_payment

S = b"secret"; NOW = 1760000000
def d(body, ts=str(NOW)):
    return body, {"X-Pay-Timestamp": ts, "X-Pay-Signature": "v1=" + hmac.new(S, ts.encode()+b"."+body, hashlib.sha256).hexdigest()}

cases = {
 "bool amount": {"event_id":"e","account_id":"a","amount_minor":True,"currency":"USD"},
 "float amount": {"event_id":"e","account_id":"a","amount_minor":1.5,"currency":"USD"},
 "negative amount": {"event_id":"e","account_id":"a","amount_minor":-1,"currency":"USD"},
 "lowercase currency": {"event_id":"e","account_id":"a","amount_minor":1,"currency":"usd"},
 "digit in currency": {"event_id":"e","account_id":"a","amount_minor":1,"currency":"US1"},
 "4-char currency": {"event_id":"e","account_id":"a","amount_minor":1,"currency":"USDD"},
 "empty event_id": {"event_id":"","account_id":"a","amount_minor":1,"currency":"USD"},
 "missing field": {"account_id":"a","amount_minor":1,"currency":"USD"},
 "non-string event_id": {"event_id":5,"account_id":"a","amount_minor":1,"currency":"USD"},
}
for name, ev in cases.items():
    b, h = d(json.dumps(ev).encode())
    try:
        parse_payment(b, h, S, NOW); print("FAIL accepted:", name)
    except InvalidNotification: print("rejected:", name)

for name, raw in [("malformed JSON", b"{not json"), ("JSON array", b"[1,2]")]:
    b, h = d(raw)
    try:
        parse_payment(b, h, S, NOW); print("FAIL accepted:", name)
    except InvalidNotification: print("rejected:", name)

b, h = d(json.dumps({"event_id":"e","account_id":"a","amount_minor":1,"currency":"USD"}).encode())
for name, fn in [
    ("missing sig header", lambda: parse_payment(b, {"X-Pay-Timestamp": NOW and str(NOW)}, S, NOW)),
    ("bad scheme", lambda: parse_payment(b, dict(h, **{"X-Pay-Signature":"v2="+h["X-Pay-Signature"][3:]}), S, NOW)),
    ("boundary 300s ok", lambda: parse_payment(b, h, S, NOW+300)),
]:
    try:
        r = fn(); print("accepted:", name, r if name.startswith("boundary") else "")
    except InvalidNotification: print("rejected:", name)
print("case-insensitive headers:", parse_payment(b, {"x-pay-timestamp": str(NOW), "x-pay-signature": h["X-Pay-Signature"]}, S, NOW))
EOF"}
